'use strict';

// ---------------------------------------------------------------------------
// Tag scheme (documented: DirectX-Specs WorkGraphs.html "DXIL Shader
// function attributes", cross-checked against DxilMetadataHelper.h and
// empirically against the spike fixture - see experimental/README.md for
// the full verification history behind every value below).
// ---------------------------------------------------------------------------

const path = require('path');

const PROP_TAGS = {
    4: 'numThreads',
    5: 'shaderFlags',
    8: 'shaderKind',
    13: 'nodeLaunchType',
    14: 'isProgramEntry',
    15: 'nodeID',
    16: 'localRootArgumentsTableIndex',
    17: 'shareInputOf',
    18: 'dispatchGrid',
    19: 'maxRecursionDepth',
    20: 'inputs',
    21: 'outputs',
    22: 'maxDispatchGrid',
};

// Confirmed for launch types 1-3 in the official spec table; 4 (mesh) is
// empirically observed in compiled output but missing from that same spec
// table (a doc gap, not a sign it's unofficial - mesh launch nodes are
// documented extensively elsewhere on that page). Unknown values fall back
// to a numeric label rather than failing, deliberately, since this table
// isn't guaranteed exhaustive.
const LAUNCH_TYPES = { 1: 'broadcasting', 2: 'coalescing', 3: 'thread', 4: 'mesh' };

// Same INPUT_TYPES/OUTPUT_TYPES vocabulary as parse-source/nodes.js - used
// here to tell an actual node-I/O parameter apart from an ordinary one
// (system-value scalars like `uint gtid`/`dtid`, or mesh-shader `out
// indices/vertices/primitives` arrays, which aren't work-graph edges).
const NODE_IO_KINDS = new Set([
    'RWDispatchNodeInputRecord',
    'DispatchNodeInputRecord',
    'RWGroupNodeInputRecords',
    'GroupNodeInputRecords',
    'ThreadNodeInputRecord',
    'EmptyNodeInput',
    'NodeOutputArray',
    'NodeOutput',
    'EmptyNodeOutputArray',
    'EmptyNodeOutput',
]);

// Matches NODE_IO_KINDS' vocabulary as a whole-word regex - used by
// original-attrs.js to pick out which raw parameter-list chunks are actual
// node I/O, kept in sync with describeParams()'s own filter below so the
// two stay positionally zippable against each other.
const NODE_IO_KIND_PATTERN = new RegExp(`\\b(${[...NODE_IO_KINDS].join('|')})\\b`);

function decodeIORecord(list) {
    const rec = {};
    if (!Array.isArray(list)) return rec;
    for (let i = 0; i < list.length; i += 2) {
        const tag = list[i];
        const val = list[i + 1];
        if (tag === 1) rec.ioFlagsRaw = val; // not decoded further - record kind/type name comes from debug info instead
        else if (tag === 2) rec.recordLayoutRaw = val; // best-effort byte layout, prefer debug-info field list for display
        else if (tag === 3) rec.maxRecords = val;
        else if (tag === 0 && Array.isArray(val)) rec.linkedNodeID = { name: val[0], index: val[1] };
        else (rec.unknownTags = rec.unknownTags || []).push([tag, val]);
    }
    return rec;
}

function decodeProps(list) {
    const out = {};
    if (!Array.isArray(list)) return out;
    for (let i = 0; i < list.length; i += 2) {
        const tag = list[i];
        const val = list[i + 1];
        const key = PROP_TAGS[tag];
        if (!key) {
            (out.unknownTags = out.unknownTags || []).push([tag, val]);
            continue;
        }
        if (key === 'nodeLaunchType') {
            out.nodeLaunchType = { raw: val, label: LAUNCH_TYPES[val] || `unknown(${val})` };
        } else if (key === 'nodeID') {
            out.nodeID = Array.isArray(val) ? { name: val[0], index: val[1] } : val;
        } else if (key === 'inputs' || key === 'outputs') {
            out[key] = Array.isArray(val) ? val.map(decodeIORecord) : [];
        } else {
            out[key] = val;
        }
    }
    return out;
}

// Walks a DISubroutineType's `types` list (element 0 is the return type,
// always null for these - node functions return void) to recover each
// node-I/O parameter's real HLSL type name, e.g.
// "GroupNodeInputRecords<ResultRecord>", including the record struct's field
// list when debug info nested it. Non-node-I/O parameters are dropped, so
// the result lines up positionally with !dx.entryPoints' inputs/outputs
// lists.
function describeParams(subprogram) {
    const subroutine = subprogram.type;
    if (!subroutine || subroutine.$kind !== 'DISubroutineType' || !Array.isArray(subroutine.types)) return [];
    return subroutine.types
        .slice(1) // drop the leading return-type slot
        .filter((t) => t && typeof t === 'object' && typeof t.name === 'string')
        .map((t) => {
            const m = t.name.match(/^(\w+)<(\w+)>$/);
            return { paramKind: m ? m[1] : t.name, recordType: m ? m[2] : null, templateParams: t.templateParams };
        })
        .filter((p) => NODE_IO_KINDS.has(p.paramKind))
        .map(({ paramKind, recordType, templateParams }) => {
            let recordFields = null;
            if (recordType && Array.isArray(templateParams)) {
                const recordDIType = templateParams[0] && templateParams[0].type;
                if (recordDIType && Array.isArray(recordDIType.elements)) {
                    recordFields = recordDIType.elements
                        .filter((e) => e && e.$kind === 'DIDerivedType')
                        .map((e) => ({ name: e.name, sizeBits: e.size }));
                }
            }
            return { paramKind, recordType, recordFields };
        });
}

function getSubprogramsByFunctionName(resolveId, named) {
    const byName = new Map();
    const cuIds = named.get('llvm.dbg.cu') || [];
    for (const cuId of cuIds) {
        const cu = resolveId(cuId);
        const subprograms = Array.isArray(cu.subprograms) ? cu.subprograms : [];
        for (const sp of subprograms) {
            if (!sp || sp.$kind !== 'DISubprogram') continue;
            const funcName = sp.function && sp.function.$func;
            if (!funcName) continue;
            byName.set(funcName, {
                name: sp.name,
                file: sp.file && sp.file.filename,
                line: sp.line,
                scopeLine: sp.scopeLine,
                params: describeParams(sp),
            });
        }
    }
    return byName;
}

// Path normalization: dxc keys file identity by the literal include-path
// spelling used at each #include site, so the same physical file can show
// up under multiple spellings in both debug-info file refs and
// dx.source.contents. Normalize both sides the same way so lookups still
// join correctly.
function normalizePath(p) {
    return path.posix.normalize(p.replace(/\\/g, '/')).replace(/^(\.\/)+/, '');
}

function getSourceFiles(resolveId, named) {
    const byPath = new Map();
    for (const id of named.get('dx.source.contents') || []) {
        const pair = resolveId(id);
        if (Array.isArray(pair) && pair.length === 2) {
            // dx.source.contents preserves the original file's line endings
            // verbatim (CRLF included, if that's how the source was saved).
            // Every downstream consumer here (extractLeadingComment,
            // original-attrs.js's line-based extraction) splits on '\n'
            // only, which would otherwise leave a stray '\r' as the last
            // character of every line - invisible in a terminal, but a
            // literal control character once it lands inside a PlantUML
            // quoted string (breaks the server's parser: "Syntax Error?
            // (Assumed diagram type: activity)", confirmed against a real
            // compile - see docs/ir-format.md). Normalized once, here, so
            // every caller downstream just sees '\n'.
            byPath.set(normalizePath(pair[0]), pair[1].replace(/\r\n/g, '\n'));
        }
    }
    return byPath;
}

// Comment extraction: the contiguous `//` block immediately preceding, no
// blank line in between. Line-based since that's what debug info gives us
// (a defining line number), not character-offset addressing. Skips back
// over the HLSL attribute lines ([Shader("node")] etc.) directly above the
// function signature first.
function extractLeadingComment(fileContent, functionLine) {
    const lines = fileContent.split('\n');
    let i = functionLine - 1 - 1; // 0-based index of the line above the function's own line
    while (i >= 0 && /^\s*\[.*\]\s*$/.test(lines[i])) i--;
    const collected = [];
    while (i >= 0 && /^\s*\/\//.test(lines[i])) {
        collected.unshift(lines[i].replace(/^\s*\/\/ ?/, ''));
        i--;
    }
    return collected.length ? collected.join('\n').trim() : null;
}

// DXIL "ResourceKind" enum - documented in dxc's DXIL.h and the DirectX
// Specs' DXIL Resource page, and empirically confirmed here: a plain
// StructuredBuffer<T> global compiled from this repo's own fixture
// produced literal `i32 12` at this exact tuple position, matching
// kStructuredBuffer below. Only used for SRV/UAV entries (see
// getResources()) - CBuffer/Sampler resource records don't carry a
// ResourceKind at the equivalent position.
const RESOURCE_KIND_NAMES = {
    0: null, // Invalid
    1: 'Texture1D',
    2: 'Texture2D',
    3: 'Texture2DMS',
    4: 'Texture3D',
    5: 'TextureCube',
    6: 'Texture1DArray',
    7: 'Texture2DArray',
    8: 'Texture2DMSArray',
    9: 'TextureCubeArray',
    10: 'TypedBuffer',
    11: 'RawBuffer',
    12: 'StructuredBuffer',
    13: 'CBuffer',
    14: 'Sampler',
    15: 'TBuffer',
    16: 'RTAccelerationStructure',
    17: 'FeedbackTexture2D',
    18: 'FeedbackTexture2DArray',
};

// dxc's LLVM type printer spells HLSL's builtin vector/matrix aliases out
// by their underlying template instantiation - "float3" prints as
// "vector<float, 3>", "float4x4" as "matrix<float, 4, 4>" - there is no
// alternate "float3" spelling anywhere in the disassembly text to recover
// instead; confirmed against a real compile of `StructuredBuffer<float3>`
// (this exact global produced the literal type name
// `class.StructuredBuffer<vector<float, 3> >`, spaces included). This maps
// that spelling back to the familiar HLSL one, applied wherever a type
// name recovered from raw disassembly text might contain it - currently
// just extractResourceValueType() below. Loops (bounded) since a matrix or
// vector can appear nested inside a larger template argument.
function normalizeDxilTypeName(name) {
    if (!name) return name;
    let current = name;
    for (let i = 0; i < 4; i++) {
        const next = current
            .replace(/\bmatrix<\s*([\w:]+)\s*,\s*(\d+)\s*,\s*(\d+)\s*>/g, (_, t, r, c) => `${t}${r}x${c}`)
            .replace(/\bvector<\s*([\w:]+)\s*,\s*(\d+)\s*>/g, (_, t, n) => `${t}${n}`);
        if (next === current) break;
        current = next;
    }
    return current.trim();
}

// The friendly element/value type name (e.g. "ItemMeta" out of
// "StructuredBuffer<ItemMeta>") isn't in the resource metadata tuple
// itself - recovered instead by finding this specific global's own
// declaration in the raw disassembly text, which spells out its full LLVM
// type name including the original HLSL template argument (dxc's LLVM
// type-naming happens to preserve it verbatim, unlike the mangled name).
// mangledName must be the exact `@"..."` global reference text (already
// escaped for regex use).
//
// Two shapes seen against real compiles, tried in order:
//  1. Bitcast-wrapped reference: the global itself is declared as the
//     opaque %dx.types.Handle, and the friendly class/struct type only
//     appears in a `bitcast (%dx.types.Handle* @"..." to %"..."*)`
//     expression at each reference site, including the resource metadata
//     tuple itself (the original, only case this was written against).
//  2. Direct declaration: needed when the resource's element type
//     requires special host-side layout (confirmed trigger: a struct
//     containing a matrix field) - dxc then declares a *second*,
//     "_legacy"-suffixed mangled global directly as the friendly type
//     (prefixed "hostlayout." - e.g. `%"hostlayout.class.StructuredBuffer
//     <MVPRootConstant>"`), referenced with no bitcast needed anywhere.
//     The "(?:[\w.]*\.)?" prefix below absorbs "hostlayout." (or any other
//     future dotted prefix) ahead of "class."/"struct.".
function extractResourceValueType(disText, mangledName) {
    if (!mangledName) return null;
    const escaped = mangledName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const typeNamePattern = '%"(?:[\\w.]*\\.)?(?:class|struct)\\.([^"]*)"';

    const bitcastRe = new RegExp(`${typeNamePattern}\\*\\s*bitcast\\s*\\(%dx\\.types\\.Handle\\*\\s*@"${escaped}"`);
    const declRe = new RegExp(`@"${escaped}"\\s*=\\s*external\\s+\\w+\\s+${typeNamePattern}`);
    const m = disText.match(bitcastRe) || disText.match(declRe);
    if (!m) return null;

    const templateMatch = m[1].match(/<(.+)>$/);
    return templateMatch ? normalizeDxilTypeName(templateMatch[1]) : null;
}

// Decodes the shared "resource base record" prefix - [ID, GlobalVariable,
// Name, Space, RangeStart (register slot), RangeSize] - documented as
// common to all four resource classes (SRV/UAV/CBV/Sampler) in the DXIL
// resource metadata schema, and what every class's entry has been
// confirmed to start with against a real compile here (SRV). RangeSize > 1
// means a resource array, not modeled further (this repo's fixtures never
// exercise one) - space/regSlot/regType/name/globalVariable are populated
// regardless.
function getResources(resolveId, named, disText) {
    const ids = named.get('dx.resources') || [];
    if (ids.length === 0) return null;
    const resourceLists = resolveId(ids[0]); // [SRVs, UAVs, CBVs, Samplers]
    if (!Array.isArray(resourceLists)) return null;
    const classes = ['SRV', 'UAV', 'CBV', 'Sampler'];
    const regTypeByClass = { SRV: 't', UAV: 'u', CBV: 'b', Sampler: 's' };
    const fixedKindByClass = { CBV: 'CBuffer', Sampler: 'Sampler' };
    const resources = [];
    resourceLists.forEach((list, classIdx) => {
        if (!Array.isArray(list)) return;
        const resourceClass = classes[classIdx];
        for (const entry of list) {
            if (!Array.isArray(entry)) continue;
            const globalRef = entry.find((e) => e && typeof e === 'object' && e.$func);
            const name = entry.find((e) => typeof e === 'string');
            const [, , , space, rangeStart, , resourceKindRaw] = entry;
            const kind =
                fixedKindByClass[resourceClass] ||
                (typeof resourceKindRaw === 'number' ? RESOURCE_KIND_NAMES[resourceKindRaw] || `unknown(${resourceKindRaw})` : null);
            resources.push({
                resourceClass,
                globalVariable: globalRef ? globalRef.$func : null,
                name: name || null,
                regType: regTypeByClass[resourceClass] || null,
                regSlot: typeof rangeStart === 'number' ? rangeStart : null,
                space: typeof space === 'number' ? space : null,
                kind,
                valueType: disText && globalRef ? extractResourceValueType(disText, globalRef.$func) : null,
                raw: entry,
            });
        }
    });
    return resources;
}

function extractFunctionBody(disText, funcName) {
    const m = disText.match(new RegExp(`define void @${funcName}\\(\\)\\s*\\{([\\s\\S]*?)\\n\\}`));
    return m ? m[1] : '';
}

// Best-effort text scan of a node's own DXIL function body for
// createHandleForLib calls, matched back to a resource by the referenced
// global's mangled name.
function findGlobalsUsed(disText, funcName, resources) {
    if (!resources || resources.length === 0) return [];
    const body = extractFunctionBody(disText, funcName);
    const used = new Set();
    for (const res of resources) {
        if (res.globalVariable && body.includes(`@"${res.globalVariable}"`)) {
            used.add(res.name || res.globalVariable);
        }
    }
    return [...used];
}

module.exports = {
    PROP_TAGS,
    LAUNCH_TYPES,
    RESOURCE_KIND_NAMES,
    NODE_IO_KINDS,
    NODE_IO_KIND_PATTERN,
    decodeIORecord,
    decodeProps,
    describeParams,
    getSubprogramsByFunctionName,
    normalizePath,
    getSourceFiles,
    extractLeadingComment,
    normalizeDxilTypeName,
    extractResourceValueType,
    getResources,
    extractFunctionBody,
    findGlobalsUsed,
};
